module max_sub_rectangle (input clk, input rst_n, input start, input [7:0] N, M, input [7:0] x, y, input [7:0] a, b, output reg [7:0] x1, y1, x2, y2, output reg done); reg [2:0] state; reg [7:0] s_count, s_max, s_current; reg [7:0] x1_reg, y1_reg, x2_reg, y2_reg; reg done_reg; parameter IDLE = 3'b000; parameter CALCSMAX = 3'b001; parameter FIND_RECT = 3'b010; parameter DONE = 3'b011; always @(posedge clk) if (!rst_n) begin state <= IDLE; s_count <= 8'b0; s_max <= 8'b0; s_current <= 8'b0; x1_reg <= 8'b0; y1_reg <= 8'b0; x2_reg <= 8'b0; y2_reg <= 8'b0; done_reg <= 1'b0; end else begin if (state == IDLE) begin if (start == 1'b1) begin state <= CALCSMAX; end end else if (state == CALCSMAX) begin wire [15:0] prod_a = a * s_count; wire [15:0] prod_b = b * s_count; if (prod_a <= N && prod_b <= M) begin s_count <= s_count + 1; s_max <= s_count; end else begin state <= FIND_RECT; s_current <= (s_count > 0) ? (s_count - 1) : 8'b0; s_max <= (s_count > 0) ? (s_count - 1) : 8'b0; end end else if (state == FIND_RECT) begin wire [15:0] w_full = a * s_current; wire [15:0] h_full = b * s_current; wire [7:0] w_val = w_full[7:0]; wire [7:0] h_val = h_full[7:0]; wire [7:0] x1_low = (x >= w_val) ? (x - w_val) : 8'b0; wire [7:0] x1_high = (x <= (N - w_val)) ? x : (N - w_val); wire [7:0] y1_low = (y >= h_val) ? (y - h_val) : 8'b0; wire [7:0] y1_high = (y <= (M - h_val)) ? y : (M - h_val); wire [7:0] valid = (x1_low <= x1_high) && (y1_low <= y1_high); if (valid) begin wire [7:0] ideal_x1 = x - (w_val >> 1); wire [7:0] ideal_y1 = y - (h_val >> 1); wire [7:0] clamped_x1 = ideal_x1; clamped_x1 = (clamped_x1 < x1_low) ? x1_low : clamped_x1; clamped_x1 = (clamped_x1 > x1_high) ? x1_high : clamped_x1; wire [7:0] clamped_y1 = ideal_y1; clamped_y1 = (clamped_y1 < y1_low) ? y1_low : clamped_y1; clamped_y1 = (clamped_y1 > y1_high) ? y1_high : clamped_y1; x1_reg <= clamped_x1; y1_reg <= clamped_y1; x2_reg <= clamped_x1 + w_val; y2_reg <= clamped_y1 + h_val; done_reg <= 1'b1; state <= DONE; end else begin if (s_current == 1) begin s_current <= 8'b0; end else begin s_current <= s_current - 1; end end end else if (state == DONE) begin end end end assign x1 = x1_reg; assign y1 = y1_reg; assign x2 = x2_reg; assign y2 = y2_reg; assign done = done_reg; endmodule